```cpp
#include <iostream>
using namespace std;

// Hàm đệ quy để tính số thứ n
int tinh_so_thu_n(int n) {
    if (n == 1) {
        return 0;
    } else if (n == 2) {
        return -1;
    } else if (n == 3) {
        return -1;
    } else {
